<?php$isAjax = isset($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest';require_once('../global.php');require_once('functions/product_function.php');$productF = new product_function();@$page = $_GET['page'];if (isset($_GET['operation'])) {  $page = 'category';}global $menu;global $subMenu;$menu = 'product';switch ($page):  case ('currency'):    $subMenu = 'Manage Currency';    require 'classes/currency.class.php';    $content = include 'currency.php';    break;  case ('category'):    $subMenu = 'Manage Category';    $content = include 'category.php';    break;  case ('scale'):    $subMenu = 'Manage Scales';    require 'classes/scale.class.php';    $content = include 'scales.php';    break;  case ('color'):    $subMenu = 'Manage Color';    require 'classes/color.class.php';    $content = include 'colors.php';    break;  default:    $content = include 'main.php';    break;endswitch;if (!$isAjax) {  include_once('../header.php');}echo  "<div id='content'><h3 class='main_heading'>" . _uc($_e['Product Management']) . "</h3>$content</div>";if (!$isAjax) {  include_once('../footer.php');}?>